const {
  SchemaField,
  NumberField,
  StringField,
  HTMLField,
  BooleanField,
  ArrayField,
  IntegerSortField,
} = foundry.data.fields;

/**
 *
 *
 *
 *
 */

export default class DetailsFields {
  static get details() {
    return {
      details: new SchemaField({
        age: new StringField({ label: "DGNS.GENERAL.age" }),
        sex: new StringField({ label: "DGNS.GENERAL.sex" }),
        height: new StringField({ label: "DGNS.GENERAL.height" }),
        weight: new StringField({ label: "DGNS.GENERAL.weight" }),
        experience: new SchemaField({
          current: new NumberField({
            integer: true,
            nullable: false,
            initial: 0,
          }),
          spent: new NumberField({
            integer: true,
            nullable: false,
            initial: 0,
          }),
          total: new NumberField({
            integer: true,
            nullable: false,
            initial: 0,
          }),
        }),
      }),
    };
  }

  static get currency() {
    return {
      currency: new SchemaField({
        drafts: new NumberField({
          integer: true,
          nullable: false,
          initial: 0,
        }),
        dinars: new NumberField({ integer: true, nullable: false, initial: 0 }),
      }),
    };
  }

  static get backrounds() {
    return {
      backgrounds: new SchemaField({
        allies: new NumberField({
          integer: true,
          nullable: false,
          initial: 0,
          min: 0,
          max: 6,
          label: "DGNS.Allies",
        }),
        authority: new NumberField({
          integer: true,
          nullable: false,
          initial: 0,
          min: 0,
          max: 6,
          label: "DGNS.Authority",
        }),
        network: new NumberField({
          integer: true,
          nullable: false,
          initial: 0,
          min: 0,
          max: 6,
          label: "DGNS.Network",
        }),
        renown: new NumberField({
          integer: true,
          nullable: false,
          initial: 0,
          min: 0,
          max: 6,
          label: "DGNS.Renown",
        }),
        resources: new NumberField({
          integer: true,
          nullable: false,
          initial: 0,
          min: 0,
          max: 6,
          label: "DGNS.Resources",
        }),
        secrets: new NumberField({
          integer: true,
          nullable: false,
          initial: 0,
          min: 0,
          max: 6,
          label: "DGNS.Secrets",
        }),
      }),
    };
  }

  static get biography() {
    return {
      biography: new HTMLField({ label: "DGNS.Biography" }),
      ownerNotes: new HTMLField({ label: "DGNS.OwnerNotes" }),
      gmNotes: new HTMLField({ label: "DGNS.GMNotes" }),
    };
  }
}
